import heapq
def minMeetingRooms(intervals):
    h = []
    for s, e in sorted(intervals):
        if h and h[0] <= s:
            heapq.heapreplace(h, e)
        else:
            heapq.heappush(h, e)
    return len(h)

brute_force_solution:
def minMeetingRooms(intervals):
    if not intervals:
        return 0
    lo = min(s for s, e in intervals)
    hi = max(e for s, e in intervals)
    return max(sum(1 for s, e in intervals if s <= t < e) for t in range(lo, hi + 1))

